/**
 * Cloudflare Worker entry: the Next.js app (built by OpenNext) plus the daily
 * jobs that Vercel Cron used to run (see "triggers" in wrangler.jsonc).
 */
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as app } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

export default {
  fetch: app.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request("https://letsbuildhome.co.zw/api/cron/ba-reminders", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      app.fetch(req, env, ctx).then(async (res: Response) => {
        console.log(`[cron] ba-reminders ${res.status} ${await res.text()}`);
      })
    );
  },
};
